import{_ as t,o as a,c as d,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Independent-Samples-Mode.md","filePath":"manual-en/Independent-Samples-Mode.md","lastUpdated":1785684581000}'),n={name:"manual-en/Independent-Samples-Mode.md"};function o(i,e,r,h,l,p){return a(),d("div",null,[...e[0]||(e[0]=[s('<h4 id="_15-13-2-independent-samples-mode" tabindex="-1">15.13.2 Independent Samples Mode <a class="header-anchor" href="#_15-13-2-independent-samples-mode" aria-label="Permalink to &quot;15.13.2 Independent Samples Mode&quot;">​</a></h4><p>The <code>GROUPS</code> subcommand invokes Independent Samples mode or ‘Groups’ mode. This mode is used to test whether two groups of values have the same population mean. In this mode, you must also use the <code>/VARIABLES</code> subcommand to tell PSPP the dependent variables you wish to test.</p><p>The variable given in the <code>GROUPS</code> subcommand is the independent variable which determines to which group the samples belong. The values in parentheses are the specific values of the independent variable for each group. If the parentheses are omitted and no values are given, the default values of 1.0 and 2.0 are assumed.</p><p>If the independent variable is numeric, it is acceptable to specify only one value inside the parentheses. If you do this, cases where the independent variable is greater than or equal to this value belong to the first group, and cases less than this value belong to the second group. When using this form of the <code>GROUPS</code> subcommand, missing values in the independent variable are excluded on a listwise basis, regardless of whether <code>/MISSING=LISTWISE</code> was specified.</p><h4 id="_15-13-2-1-example-independent-samples-t-test" tabindex="-1">15.13.2.1 Example - Independent Samples T-test <a class="header-anchor" href="#_15-13-2-1-example-independent-samples-t-test" aria-label="Permalink to &quot;15.13.2.1 Example - Independent Samples T-test&quot;">​</a></h4><p>A researcher wishes to know whether within a population, adult males are taller than adult females. The samples are drawn from the population under investigation and recorded in the file physiology.sav.</p><p>As previously noted (see <a href="./Identifying-incorrect-data">Identifying incorrect data</a>), one sample in the dataset contains a height value which is clearly incorrect. So this is excluded from the analysis using the <code>SELECT</code> command.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&#39;physiology.sav&#39;.  select if (height &gt;= 200).  t-test /variables = height        /groups = sex(0,1).</span></span></code></pre></div><p><strong>Example 15.7:</strong> Running a independent samples T-Test after excluding all observations less than 200kg</p><p>The null hypothesis is that both males and females are on average of equal height.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>Screenshot 15.6:</strong> Using the Independent Sample T-test dialog, to test for differences of <strong>height</strong> between values of <strong>sex</strong></p><p>In this case, the grouping variable is <strong>sex</strong> , so this is entered as the variable for the <code>GROUP</code> subcommand. The group values are 0 (male) and 1 (female).</p><p>If you are running the proceedure using syntax, then you need to enter the values corresponding to each group within parentheses. If you are using the graphic user interface, then you have to open the “Define Groups” dialog box and enter the values corresponding to each group as shown in Screenshot 15.7. If, as in this case, the dataset has defined value labels for the group variable, then you can enter them by label or by value.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>Screenshot 15.7:</strong> Setting the values of the grouping variable for an Independent Samples T-test</p><p>From Result 15.5, one can clearly see that the <em>sample</em> mean height is greater for males than for females. However in order to see if this is a significant result, one must consult the T-Test table.</p><p>The T-Test table contains two rows; one for use if the variance of the samples in each group may be safely assumed to be equal, and the second row if the variances in each group may not be safely assumed to be equal.</p><p>In this case however, both rows show a 2-tailed significance less than 0.001 and one must therefore reject the null hypothesis and conclude that within the population the mean height of males and of females are unequal.</p><table tabindex="0"><thead><tr><th></th><th></th><th>F</th><th>Sig.</th><th>t</th><th>df</th><th>Sig. (2-tailed)</th><th>Mean Difference</th><th>Std. Error Difference</th><th>95% Confidence Interval of the Difference</th><th></th></tr></thead><tbody><tr><td></td><td>Group</td><td>N</td><td>Mean</td><td>Std. Deviation</td><td>S.E. Mean</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Height in millimeters</td><td>Male</td><td>22</td><td>1796.49</td><td>49.71</td><td>10.60</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Female</td><td>17</td><td>1610.77</td><td>25.43</td><td>6.17</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td>Levene&#39;s Test for Equality of Variances</td><td>T-Test for Equality of Means</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td>Lower</td><td>Upper</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Height in millimeters</td><td>Equal variances assumed</td><td>.97</td><td>.331</td><td>14.02</td><td>37.00</td><td>.000</td><td>185.72</td><td>13.24</td><td>158.88</td><td>212.55</td></tr><tr><td>Equal variances not assumed</td><td></td><td></td><td>15.15</td><td>32.71</td><td>.000</td><td>185.72</td><td>12.26</td><td>160.76</td><td>210.67</td><td></td></tr></tbody></table><p><strong>Result 15.5:</strong> The results of an independent samples T-test of <strong>height</strong> by <strong>sex</strong></p>',21)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
